function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'FirstUnique' || !Array.isArray(args[0]) || args[0].length !== 1 || !Array.isArray(args[0][0])) return 'Start with FirstUnique(nums).';
  const nums = args[0][0];
  const goodValue = (v) => Number.isInteger(v) && v >= 1 && v <= 100000000;
  if (nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 10^5 values.';
  if (!nums.every(goodValue)) return 'Each value in nums is between 1 and 10^8.';
  if (operations.length - 1 > 50000) return 'At most 5 * 10^4 calls to showFirstUnique and add.';
  for (let i = 1; i < operations.length; i++) {
    const a = args[i];
    if (!Array.isArray(a)) return 'Each call needs an argument list.';
    if (operations[i] === 'showFirstUnique') {
      if (a.length !== 0) return 'showFirstUnique takes no arguments.';
    } else if (operations[i] === 'add') {
      if (a.length !== 1 || !goodValue(a[0])) return 'add needs one value between 1 and 10^8.';
    } else {
      return 'Only showFirstUnique and add can follow the constructor.';
    }
  }
  return null;
}

