class FirstUnique {
  constructor(nums) {
    this.queue = [];
    this.head = 0;
    this.count = new Map();
    for (const num of nums) {
      this.add(num);
    }
  }

  showFirstUnique() {
    while (this.head < this.queue.length && this.count.get(this.queue[this.head]) > 1) {
      this.head++;
    }
    if (this.head === this.queue.length) {
      return -1;
    }
    return this.queue[this.head];
  }

  add(value) {
    const seen = this.count.get(value) || 0;
    this.count.set(value, seen + 1);
    if (seen === 0) {
      this.queue.push(value);
    }
  }
}

