function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const spread = rand() < 0.5 ? int(2, large ? 3000 : 8) : 100000000;
  const pick = () => int(1, spread);
  const length = large ? (rand() < 0.6 ? 2000 : int(1, 50)) : int(1, 6);
  const nums = Array.from({ length }, pick);
  const calls = large ? 499 : int(1, 12);
  const operations = ['FirstUnique'];
  const args = [[nums]];
  // Track the queue so that some additions duplicate the current first unique value.
  const order = [];
  const count = new Map();
  const push = (value) => {
    if (!count.has(value)) order.push(value);
    count.set(value, (count.get(value) || 0) + 1);
  };
  nums.forEach(push);
  for (let i = 0; i < calls; i++) {
    if (rand() < 0.4) {
      operations.push('showFirstUnique');
      args.push([]);
      continue;
    }
    const roll = rand();
    let value = pick();
    if (roll < 0.4) {
      const front = order.find(v => count.get(v) === 1);
      if (front !== undefined) value = front;
    } else if (roll < 0.55) {
      value = nums[Math.floor(rand() * nums.length)];
    }
    operations.push('add');
    args.push([value]);
    push(value);
  }
  return [operations, args];
}
